    def __init__(self, cfg: dict, settings: dict):
        self.cfg = cfg or {}
        self.settings = settings or {}

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        return False

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        raise NotImplementedError


class CrisisBehavior(Behavior):
    name = "crisis"
    priority = 100

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        s = self.cfg
        if not state.connected:
            bb.stop_reason = "cliente desconectado"
            return True
        if s.get("pause_on_player", True):
            for c in state.creatures:
                if c.is_self:
                    continue
                if c.is_player or c.kind == CreatureKind.PLAYER:
                    if state.player.pos.distance(c.pos) <= int(s.get("player_range", 7)):
                        bb.human_seen = True
                        bb.stop_reason = "jugador/GM detectado"
                        return True
        if state.player.hp_pct <= int(s.get("panic_hp_pct", 10)):
            bb.stop_reason = "HP crítica"
            return True
        return False

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        s = self.cfg
        if not state.connected:
            if bb.ready("reconnect", float(s.get("reconnect_cooldown", 5))):
                inp.press(s.get("reconnect_key", "F1"))
                bb.mark("reconnect")
            return
        if bb.human_seen:
            bb.paused = True
            if s.get("logout_on_player"):
                inp.press(s.get("logout_key", "F12"))
            return
        threat = nearest(state, is_enemy, max_range=int(s.get("flee_detect_range", 5)))
        if threat is not None and bb.ready("flee", 0.3):
            away = Vec3(
                state.player.pos.x * 2 - threat.pos.x,
                state.player.pos.y * 2 - threat.pos.y,
                state.player.pos.z,
            )
            direction = state.player.pos.direction_to(away)
            if direction >= 0:
                inp.move(direction)
            bb.mark("flee")


class HealingBehavior(Behavior):
    name = "heal"
    priority = 90

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True):
            return False
        s = self.cfg
        cd = float(s.get("cooldown", 1.0))
        if state.player.hp_pct <= int(s.get("player_hp_pct", 60)) and bb.ready("player_heal", cd):
            return True
        pk = state.active_pokemon()
        if pk and pk.hp_pct <= int(s.get("pokemon_hp_pct", 40)) and bb.ready("pokemon_heal", cd):
            return True
        return False

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        s = self.cfg
        if state.player.hp_pct <= int(s.get("player_hp_pct", 60)):
            inp.press(s.get("player_heal_key", "F2"))
            bb.mark("player_heal")
            return
        pk = state.active_pokemon()
        if pk and pk.hp_pct <= int(s.get("pokemon_hp_pct", 40)):
            inp.press(s.get("pokemon_heal_key", "F3"))
            bb.mark("pokemon_heal")


class CaptureBehavior(Behavior):
    name = "capture"
    priority = 80

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True):
            return False
        s = self.cfg
        names = {n.lower() for n in s.get("targets", [])}
        catch_all = bool(s.get("catch_all", False))
        threshold = int(s.get("hp_threshold", 30))

        def candidate(c: Creature) -> bool:
            if not c.attackable:
                return False
            if not catch_all and names and c.name.lower() not in names:
                return False
            return c.hp_pct <= threshold

        target = nearest(state, candidate, max_range=int(s.get("range", 6)))
        if target is None:
            return False
        bb.target_cid = target.cid
        return bb.ready("capture", float(s.get("cooldown", 1.5)))

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        target = state.creature(bb.target_cid)
        if target is None:
            return
        inp.click_tile(target.pos, {"player": state.player})
        inp.press(self.cfg.get("ball_key", "F4"))
        bb.mark("capture")


class CombatBehavior(Behavior):
    name = "combat"
    priority = 70

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True):
            return False
        target = nearest(state, is_enemy, max_range=int(self.cfg.get("detect_range", 7)))
        if target is None:
            return False
        bb.target_cid = target.cid
        return True

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        s = self.cfg
        target = state.creature(bb.target_cid)
        if target is None:
            return
        if state.player.pos.distance(target.pos) > int(s.get("attack_range", 1)):
            direction = state.player.pos.direction_to(target.pos)
            if direction >= 0 and bb.ready("approach", float(s.get("approach_cooldown", 0.15))):
                inp.move(direction)
                bb.mark("approach")
            return
        moves = s.get("moves", ["F5", "F6", "F7", "F8"])
        if not moves:
            return
        if bb.ready("attack", float(s.get("cooldown", 0.7))):
            inp.click_tile(target.pos, {"player": state.player})
            index = bb.notes.get("move_idx", 0)
            inp.press(moves[index % len(moves)])
            bb.notes["move_idx"] = index + 1
            bb.mark("attack")


class LootBehavior(Behavior):
    name = "loot"
    priority = 50

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True):
            return False
        s = self.cfg
        if state.in_battle:
            return False
        if not bb.ready("loot", float(s.get("cooldown", 1.0))):
            return False
        for c in state.creatures:
            if c.hp_pct <= 0 and state.player.pos.distance(c.pos) <= int(s.get("range", 2)):
                bb.notes["corpse"] = (c.pos.x, c.pos.y)
                return True
        return bool(s.get("periodic_quickloot", False))

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        s = self.cfg
        pos = bb.notes.pop("corpse", None)
        if pos is not None:
            inp.click_tile(Vec3(pos[0], pos[1], state.player.pos.z), {"player": state.player})
        inp.press(s.get("loot_key", "F9"))
        bb.mark("loot")


def make_walkable(state: GameState, static_map: Optional[list] = None):
    if static_map:
        rows = static_map

        def walk_static(x: int, y: int) -> bool:
            if 0 <= y < len(rows) and 0 <= x < len(rows[y]):
                return rows[y][x] not in "#X"
            return False

        return walk_static
    if state.tiles:
        z = state.player.pos.z

        def walk_tiles(x: int, y: int) -> bool:
            tile = state.tiles.get((x, y, z))
            return True if tile is None else tile.walkable

        return walk_tiles
    return lambda x, y: True


class RouteBehavior(Behavior):
    name = "route"
    priority = 10

    def __init__(self, cfg: dict, settings: dict, route: Optional[Route]):
        super().__init__(cfg, settings)
        self.route = route

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True) or self.route is None:
            return False
        return True

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        walkable = make_walkable(state, self.cfg.get("static_map"))
        path = self.route.plan(
            state.player.pos, walkable, arrive_distance=int(self.cfg.get("arrive_distance", 1))
        )
        if not path:
            self.route.advance()
            return
        nxt = path[1] if len(path) > 1 else path[0]
        direction = state.player.pos.direction_to(nxt)
        if direction >= 0 and bb.ready("route", float(self.cfg.get("step_delay", 0.25))):
            inp.move(direction)
            bb.mark("route")


def build_behaviors(cfg: dict, route: Optional[Route]) -> list[Behavior]:
    behaviors_cfg = cfg.get("behaviors", {})
    settings = cfg.get("settings", {})
    behaviors: list[Behavior] = [
        CrisisBehavior(behaviors_cfg.get("crisis", {}), settings),
        HealingBehavior(behaviors_cfg.get("healing", {}), settings),
        CaptureBehavior(behaviors_cfg.get("capture", {}), settings),
        CombatBehavior(behaviors_cfg.get("combat", {}), settings),
        LootBehavior(behaviors_cfg.get("loot", {}), settings),
        RouteBehavior(behaviors_cfg.get("route", {}), settings, route),
    ]
    behaviors.sort(key=lambda b: b.priority, reverse=True)
    return behaviors

from __future__ import annotations

import time
from typing import Optional

from .behaviors import Blackboard, build_behaviors
from .models import CreatureKind, GameState
from .pathfinding import Route


class Bot:
    def __init__(self, source, inp, cfg: dict, verbose: bool = False):
        self.source = source
        self.inp = inp
        self.cfg = cfg
        self.verbose = verbose
        self.ticks = 0
        route = self._build_route(cfg)
        self.route = route
        self.bb = Blackboard(route=route)
        self.behaviors = build_behaviors(cfg, route)

    @staticmethod
    def _build_route(cfg: dict) -> Optional[Route]:
        rcfg = cfg.get("route") or {}
        if not rcfg.get("waypoints"):
            return None
        return Route.from_config(
            rcfg["waypoints"],
            loop=bool(rcfg.get("loop", True)),
            ping_pong=bool(rcfg.get("ping_pong", False)),
        )

    def tick(self):
        state = self.source.read_state()
        self._manage_pause(state)
        chosen = None
        for behavior in self.behaviors:
            if behavior.name != "crisis" and self.bb.paused:
                break
            try:
                if behavior.evaluate(state, self.bb):
                    behavior.act(state, self.bb, self.inp)
                    chosen = behavior.name
                    break
            except Exception as exc:
                if self.verbose:
                    print(f"[!] {behavior.name}: {exc}")
        self.ticks += 1
        return state, chosen

    def _manage_pause(self, state: GameState) -> None:
        crisis_cfg = self.cfg.get("behaviors", {}).get("crisis", {})
        if self.bb.human_seen:
            still_there = False
            for c in state.creatures:
                if c.is_self:
                    continue
                if c.is_player or c.kind == CreatureKind.PLAYER:
                    if state.player.pos.distance(c.pos) <= int(crisis_cfg.get("player_range", 7)):
                        still_there = True
                        break
            if not still_there:
                self.bb.human_seen = False
        if self.bb.paused and not self.bb.human_seen:
            self.bb.paused = False
            self.bb.stop_reason = ""

    def run(self, max_ticks: Optional[int] = None) -> None:
        tick_seconds = float(self.cfg.get("settings", {}).get("tick_seconds", 0.1))
        while max_ticks is None or self.ticks < max_ticks:
            state, chosen = self.tick()
            if self.verbose:
                print(self._format(state, chosen))
            time.sleep(tick_seconds)

    def _format(self, state: GameState, chosen: Optional[str]) -> str:
        p = state.player
        flag = f"PAUSA({self.bb.stop_reason})" if self.bb.paused else (chosen or "idle")
        return (
            f"t={self.ticks:04d} pos=({p.pos.x},{p.pos.y},{p.pos.z}) "
            f"hp={p.hp_pct}% mp={p.mp_pct}% enemigos={sum(1 for c in state.creatures if c.attackable)} "
            f"-> {flag}"
        )

from __future__ import annotations

import struct
from typing import Optional

from .memory import Process

VALUE_FORMATS = {
    "i32": "<i", "u32": "<I", "i16": "<h", "u16": "<H",
    "u8": "<B", "f32": "<f", "f64": "<d",
}

MAX_REGION = 0x4000000


def scan_value(process: Process, value, vtype: str = "i32", max_hits: int = 200) -> list[int]:
    fmt = VALUE_FORMATS[vtype]
    target = struct.pack(fmt, value)
    return _scan_bytes(process, target, max_hits)


def scan_bytes(process: Process, needle: bytes, max_hits: int = 200) -> list[int]:
    return _scan_bytes(process, needle, max_hits)


def _scan_bytes(process: Process, needle: bytes, max_hits: int) -> list[int]:
    hits: list[int] = []
    for base, size, _protect in process.regions(readable_only=True):
        if size > MAX_REGION:
            continue
        data = process.try_read_bytes(base, size)
        if not data:
            continue
        start = 0
        while len(hits) < max_hits:
            index = data.find(needle, start)
            if index < 0:
                break
            hits.append(base + index)
            start = index + 1
    return hits


def refine(process: Process, addresses: list[int], value, vtype: str = "i32") -> list[int]:
    fmt = VALUE_FORMATS[vtype]
    target = struct.pack(fmt, value)
    return [a for a in addresses if process.try_read_bytes(a, len(target)) == target]


def find_pointers_to(process: Process, target: int, max_offset: int = 0x400, max_hits: int = 64) -> list[tuple[int, int]]:
    ptr_size = process.pointer_size
    fmt = "<I" if ptr_size == 4 else "<Q"
    lo, hi = target, target + max_offset
    results: list[tuple[int, int]] = []
    for base, size, _protect in process.regions(readable_only=True):
        if size > MAX_REGION:
            continue
        data = process.try_read_bytes(base, size)
        if not data:
            continue
        step = ptr_size
        for off in range(0, len(data) - step + 1, step):
            value = struct.unpack_from(fmt, data, off)[0]
            if lo <= value <= hi:
                results.append((base + off, value))
                if len(results) >= max_hits:
                    return results
    return results


def pointer_scan(process: Process, target: int, levels: int = 3, max_offset: int = 0x400) -> list[list[int]]:
    chains: list[list[int]] = []

    def walk(address: int, chain: list[int], depth: int) -> None:
        if depth > levels:
            return
        for location, _value in find_pointers_to(process, address, max_offset=max_offset, max_hits=16):
            module_base = _module_containing(process, location)
            if module_base is not None:
                chains.append([module_base, location] + chain)
                continue
            walk(location, [location] + chain, depth + 1)

    walk(target, [], 1)
    return chains


def _module_containing(process: Process, address: int) -> Optional[int]:
    for name, (base, size) in process._modules.items():
        if base <= address < base + size:
            return base
    return None


def dump(process: Process, address: int, size: int = 128) -> str:
    data = process.try_read_bytes(address, size)
    if not data:
        return ""
    lines = []
    for offset in range(0, len(data), 16):
        chunk = data[offset : offset + 16]
        hexpart = " ".join(f"{b:02X}" for b in chunk)
        asciipart = "".join(chr(b) if 32 <= b < 127 else "." for b in chunk)
        lines.append(f"{address + offset:016X}  {hexpart:<47}  {asciipart}")
    return "\n".join(lines)

