from pxg_bot.memory import find_pid, open_process
pid=find_pid("pxgme-linux"); proc=open_process(pid=pid)
MASK=(1<<47)-1
T={ 'str':(~4)&0xFFFFFFFF,'tab':(~11)&0xFFFFFFFF,'udata':(~12)&0xFFFFFFFF,'func':(~8)&0xFFFFFFFF,'lightud':(~3)&0xFFFFFFFF,'thread':(~6)&0xFFFFFFFF}
def q(a): return struct.unpack("<Q", proc.read_bytes(a,8))[0]
def u32(a): return struct.unpack("<I", proc.read_bytes(a,4))[0]
def decode(v):
    it64=v-(1<<64) if v>=(1<<63) else v
    return (it64>>47)&0xFFFFFFFF, v&MASK
def tn(t):
    for k,v in T.items():
        if t==v: return k
    return "number" if t<=(~13)&0xFFFFFFFF else hex(t)
def gstr(p):
    try:
        ln=u32(p+20); return proc.read_cstring(p+24,min(ln,80))
    except Exception: return "?"

def iter_table(tab):
    node=q(tab+40); hmask=u32(tab+52); arr=q(tab+16); asize=u32(tab+48)
    if arr and asize:
        for i in range(min(asize,50)):
            yield (i, struct.unpack("<Q",proc.read_bytes(arr+i*8,8))[0])
    if node:
        for i in range(hmask+1):
            np_=node+i*24
            try: k=q(np_+8); v=q(np_)
            except Exception: continue
            yield (k, v)

L=0x7f1fd6c7d380
env=q(L+72)
print("=== globals no-func ===")
for k,v in iter_table(env):
    kt,kp=decode(k); vt,vp=decode(v)
    if kt==T['str']:
        name=gstr(kp)
        if vt in (T['udata'],T['lightud'],T['tab'],T['thread']):
            print(f"  {name!r} -> {tn(vt)} ptr=0x{vp:X}")
G=q(L+16); reg=q(G+272) if False else None
# registry
import struct as st
regtv=st.unpack("<Q",proc.read_bytes(G+272,8))[0]
rt,rp=decode(regtv)
print(f"\nregistry TValue type={tn(rt)} ptr=0x{rp:X}")
if rt==T['tab']:
    print("=== registry entries (no-func) ===")
    n=0
    for k,v in iter_table(rp):
        kt,kp=decode(k); vt,vp=decode(v)
        key = repr(gstr(kp)) if kt==T['str'] else (f"num:{st.unpack('<i',st.pack('<Q',k&0xFFFFFFFF))[0]}" if kt<= (~13)&0xFFFFFFFF else f"<{tn(kt)}>")
        if vt in (T['udata'],T['lightud'],T['tab']):
            print(f"  key={key} -> {tn(vt)} ptr=0x{vp:X}")
            n+=1
        if n>40: break
proc.close()
