    name = "route"
    priority = 10

    def __init__(self, cfg: dict, settings: dict, route: Optional[Route]):
        super().__init__(cfg, settings)
        self.route = route

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True) or self.route is None:
            return False
        return True

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        walkable = make_walkable(state, self.cfg.get("static_map"))
        path = self.route.plan(
            state.player.pos, walkable, arrive_distance=int(self.cfg.get("arrive_distance", 1))
        )
        if not path:
            self.route.advance()
            return
        nxt = path[1] if len(path) > 1 else path[0]
        direction = state.player.pos.direction_to(nxt)
        if direction >= 0 and bb.ready("route", float(self.cfg.get("step_delay", 0.25))):
            if bb.humanizer is not None and bb.humanizer.chance(0.05):
                bb.mark("route")
                return
            inp.move(direction)
            bb.mark("route")

