class CaptureBehavior(Behavior):
    name = "capture"
    priority = 80

    def evaluate(self, state: GameState, bb: Blackboard) -> bool:
        if bb.paused or not self.cfg.get("enabled", True):
            return False
        s = self.cfg
        names = {n.lower() for n in s.get("targets", [])}
        catch_all = bool(s.get("catch_all", False))
        threshold = int(s.get("hp_threshold", 30))
        if bb.humanizer is not None:
            threshold = int(bb.humanizer.jitter(threshold, "threshold_jitter_pct"))

        def candidate(c: Creature) -> bool:
            if not c.attackable:
                return False
            if not catch_all and names and c.name.lower() not in names:
                return False
            return c.hp_pct <= threshold

        target = nearest(state, candidate, max_range=int(s.get("range", 6)))
        if target is None:
            return False
        bb.target_cid = target.cid
        return bb.ready("capture", float(s.get("cooldown", 1.5)))

    def act(self, state: GameState, bb: Blackboard, inp) -> None:
        target = state.creature(bb.target_cid)
        if target is None:
            return
        inp.click_tile(target.pos, {"player": state.player})
        inp.press(self.cfg.get("ball_key", "F4"))
        bb.mark("capture")

